def svg(fig,name):
 p=assets/name;fig.savefig(p,bbox_inches='tight');fig.savefig(p.with_suffix('.png'),bbox_inches='tight',dpi=150);plt.close(fig)
 return 'data:image/svg+xml;base64,'+base64.b64encode(p.read_bytes()).decode()
def source_frame(video_id,name):
 sample=next(s for s in report['samples'] if s['video_id']==video_id)
 cap=cv2.VideoCapture(str(ROOT/'results/demo_v4/public/clips_v4'/(sample['source_sha256']+'.mp4')));cap.set(cv2.CAP_PROP_POS_MSEC,1500);ok,frame=cap.read();cap.release()
 if not ok:raise ValueError('Missing demo frame')
 data=cv2.imencode('.jpg',frame,[cv2.IMWRITE_JPEG_QUALITY,88])[1].tobytes()
 return 'data:image/jpeg;base64,'+base64.b64encode(data).decode()
fig,ax=plt.subplots(figsize=(11,4.6));values=[r['mean_test_macro_f1'] for r in experiment['results']]+[np.mean([m['macro_f1'] for m in report['metrics'] if m['modality']=='cv_selected'])];bars=ax.bar(['Sinir ağı\nGörüntü','Sinir ağı\nSes','Sinir ağı\nBirleşik','Klasik\nCV seçimi'],values,color=['#82b6b0','#d5be89','#b6ef83','#778990'],width=.58)
