traces=experiment['history']['fusion'];epochs=[r['epoch'] for r in traces[0]];train=np.array([[r['train_loss'] for r in trace] for trace in traces]);val=np.array([[r['validation_loss'] for r in trace] for trace in traces])
fig,axes=plt.subplots(1,2,figsize=(12,4.4))
for arr,label,color in [(train,'Eğitim','#b6ef83'),(val,'Doğrulama','#d5be89')]:
 axes[0].plot(epochs,arr.mean(0),label=label,color=color,linewidth=2);axes[0].fill_between(epochs,arr.mean(0)-arr.std(0),arr.mean(0)+arr.std(0),color=color,alpha=.12)
axes[0].set_xlabel('Epoch');axes[0].set_ylabel('Sınıf ağırlıklı görev kaybı');legend=axes[0].legend(facecolor='#1a2520',edgecolor='none');plt.setp(legend.get_texts(),color='#eff5ed')
f1=np.array([[r['validation_mean_f1'] for r in trace] for trace in traces]);axes[1].plot(epochs,f1.mean(0),color='#82b6b0',linewidth=2);axes[1].fill_between(epochs,f1.mean(0)-f1.std(0),f1.mean(0)+f1.std(0),alpha=.15,color='#82b6b0');axes[1].axvline(60,linestyle='--',color='#d5be89');axes[1].set_xlabel('Epoch');axes[1].set_ylabel('Ortalama doğrulama macro F1');axes[1].set_ylim(0,.65)
for ax in axes:ax.spines[['top','right']].set_visible(False);ax.grid(alpha=.12)
