slides=[];notes=[]
def add(title,body,note,kind=''):
 slides.append(f'<section class="slide {kind}" data-title="{html.escape(title)}"><h1>{title}</h1>{body}<aside>{html.escape(note)}</aside></section>');notes.append((title,note))
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def image(src,alt):return f'<img src="{src}" alt="{html.escape(alt)}">'
add('Köpek davranışının<br>ses ve pozla analizi',f'<div class="columns"><div><p class="lead">Donmuş ön-eğitimli kodlayıcılarla<br>çok görevli sinir ağı</p><p>Nilüfer Öden<br>Bilgisayar Mühendisliği</p><p class="muted">Çalışan prototip ve keşifsel deneyler</p></div>{image(cover,"Projede üretilen gerçek köpek poz önizlemesi")}</div>', 'Bu çalışmada videodaki köpeğin pozunu ve kaydın sesini birlikte kullanarak beş gözlenebilir davranışı tahmin ediyorum. Derin öğrenme kısmında ön-eğitimli kodlayıcılardan özellik çıkarıyor, kendi çok görevli birleşim ağımı eğitiyorum. Duygu sınıflandırması doğrulanmış bir çıktı değildir.')
add('Veri ve görev tanımı',table(['Veri','Adet / kapsam'],[['Toplam video',127],['Tam davranış etiketi',97],['Eğitim / test','72 / 25 video'],['Eksik etiketli, eğitime girmeyen',30],['Hedefler','Aktivite, vücut, duruş, kuyruk, kulak']])+'<p class="muted">Etiket birimi videodur. Kesin içerik kopyaları SHA256 ile gruplanır. Köpek kimlikleri bilinmiyor. Kaynak: Rao, Sanil ve Ankitha K, Mendeley 5g5hg9hrkv.</p>','97 tam etiketli videonun 72 tanesini eğitim, 25 tanesini test olarak korudum. Eksik etiketli 30 videoyu yalnız galeride gösteriyorum. Test daha önce incelendiği için bağımsız yeni doğrulama demiyorum. Aynı köpeğin farklı dosyalarda bulunması hâlâ mümkün. Veri kaynağı: https://data.mendeley.com/datasets/5g5hg9hrkv/2')
add('Ön-eğitimli özellik çıkarımı', '<div class="columns"><div><h2>Görüntü</h2><p>YOLOv8n köpek kutusu<br>RTMPose-S: 39 anahtar nokta<br>Normalize poz ve hareket özetleri</p><h2>Ses</h2><p>16 kHz mono kayıt<br>YAMNet: 1024 boyutlu temsil<br>Ses olayı skorlarının özetleri</p></div><div><h2>Ortak kapsam</h2><p>İlk 60 saniye<br>Yaklaşık 2 kare/sn poz örnekleme<br>Video düzeyinde özetleme</p><p class="muted">Kodlayıcılar donmuş durumda. YOLOv8s/m iyileştirmeleri galeri çizimine aittir; eğitim özellikleri YOLOv8n önbelleğinden gelir.</p></div></div>', 'Eğitimdeki görüntü özelliklerinin YOLOv8n ile çıkarıldığına ağırlık dosyası özetinden bakarak emin oldum. Galeride daha yeni YOLOv8s ve m önizlemeleri de var, ancak bunları sınıflandırma eğitimine karıştırmıyorum. YAMNet resmi 1024 boyutlu temsilini kullanıyor. Kaynaklar: https://github.com/tensorflow/models/tree/master/research/audioset/yamnet ve https://deeplabcut.github.io/DeepLabCut/docs/ModelZoo.html')
add('Eğittiğimiz FusionNet',table(['Katman','Yapı'],[['Poz dalı',f'{meta["visual_dim"]} girdi → Dense 64 → LayerNorm → GELU → Dropout → Dense 32'],['Ses dalı',f'{meta["audio_dim"]} girdi → Dense 64 → LayerNorm → GELU → Dropout → Dense 32'],['Birleşim','32 + 32 → Dense 32 → GELU → Dropout'],['Çıkış','5 görev başlığı, her görev için ayrı softmax'],['Aktif eğitilebilir parametre',f'{meta["trainable_parameters"]:,}']])+'<p class="muted">Uçtan uca piksel/ses yeniden eğitimi uygulanmadı. Bizim eğittiğimiz kısım özellik kodlayıcıları, birleşim ve davranış başlıklarıdır.</p>', 'Her dal 32 boyutlu bir gösterime ulaşıyor. Birleşik model bunları birleştirip beş davranışı aynı anda öğreniyor. Beş görev ortak ağırlıkları kullanıyor. Yalnız görev başlıkları değil, iki sayısal özellik kodlayıcısı ve ortak birleşim katmanı da gradyanla eğitiliyor. Ön-eğitimli poz ve ses omurgaları sabit.')
add('Eğitim ve model seçimi', '<div class="columns"><div><h2>Eğitim</h2><p>AdamW, öğrenme oranı 0,001<br>Ağırlık çürümesi 0,01<br>Dropout 0,35<br>Sınıf ağırlıklı çok görevli çapraz entropi</p></div><div><h2>Seçim</h2><p>Yalnız 72 eğitim videosunda 3 katlı GroupKFold<br>Aday epoch: 20, 40, 60, 80<br>Birleşik ağda seçim: 60 epoch</p></div></div><p class="muted">Eksik/görünmeyen hedeflerde kayıp maskelenir. Doldurma ve ölçekleme her katın eğitim kısmında öğrenilir. Başlangıç tohumu: 42.</p>', 'Test kümesini erken durdurma veya epoch seçimi için kullanmadım. Üç eğitim katının ortalama F1 değerine göre birleşik ağda 60 epoch seçtim. Üç modun seçimlerini test sonuçlarına bakmadan dosyaya kaydettim. Tek başlangıç tohumu kullandığım için tohumlar arası kararlılık iddiasında bulunmuyorum.')
add('Öğrenme eğrileri',image(curves,'Üç eğitim CV katında kayıp ve doğrulama F1 eğrileri')+'<p class="muted">Çizgiler üç eğitim CV katının ortalaması, gölgeler katlar arası standart sapmadır. Güven aralığı değildir.</p>', 'Sol panel eğitim ve doğrulama kayıplarını, sağ panel ortalama doğrulama F1 değerini gösteriyor. Eğitim kaybı azalırken doğrulama aynı ölçüde iyileşmiyorsa küçük veri nedeniyle aşırı uyum riski vardır. Kesikli çizgi eğitim CV ile seçtiğimiz 60 epoch değeridir.')
