css='''*{box-sizing:border-box}html,body{margin:0;background:#101815;color:#eff5ed;font-family:Arial,sans-serif}body{overflow:hidden}.slide{display:none;width:1280px;height:720px;padding:56px 64px;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(var(--scale,1));transform-origin:center;background:#101815}.slide.active{display:block}h1{font-size:43px;line-height:1.16;letter-spacing:-1.2px;margin:0 0 28px;font-weight:700;color:#b6ef83}h2{font-size:27px;margin:12px 0;color:#d5be89}p{font-size:25px;line-height:1.45;margin:18px 0}.lead{font-size:32px;line-height:1.4}.muted{font-size:20px;color:#afbfaf;line-height:1.4}.columns{display:grid;grid-template-columns:1fr 1fr;gap:42px;align-items:center}.columns img{width:100%;height:425px;object-fit:contain}section>img{display:block;width:100%;height:405px;object-fit:contain}table{width:100%;border-collapse:collapse;font-size:23px;line-height:1.35}td,th{text-align:left;border-bottom:1px solid #34463b;padding:16px 12px;vertical-align:top}th{color:#d5be89;font-size:21px}aside{display:none}body.notes aside{display:block;position:absolute;left:45px;right:45px;bottom:28px;background:#233329;padding:20px;font-size:18px;line-height:1.45}nav{position:fixed;bottom:12px;left:20px;right:20px;display:flex;justify-content:space-between;align-items:center;color:#afbfaf;font-size:14px}button{background:#233329;color:#eff5ed;border:1px solid #52654f;padding:7px 15px;border-radius:5px;cursor:pointer}a{color:#b6ef83}@media print{body{overflow:visible;background:white}nav{display:none}.slide{display:block!important;position:relative;left:0;top:0;transform:none;width:1280px;height:720px;break-after:page;page-break-after:always;print-color-adjust:exact;-webkit-print-color-adjust:exact}aside{display:none!important}@page{size:338.67mm 190.5mm;margin:0}}'''
script='''const slides=[...document.querySelectorAll('.slide')];let index=Math.max(0,Math.min(slides.length-1,Number(location.hash.slice(1)||1)-1));function draw(){slides.forEach((s,i)=>s.classList.toggle('active',i===index));document.getElementById('count').textContent=(index+1)+' / '+slides.length;location.replace('#'+(index+1))}function resize(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1280,(innerHeight-35)/720))}function move(n){index=Math.max(0,Math.min(slides.length-1,index+n));draw()}document.getElementById('prev').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);document.getElementById('notes').onclick=()=>document.body.classList.toggle('notes');addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();move(1)}if(['ArrowLeft','PageUp'].includes(e.key))move(-1);if(e.key.toLowerCase()==='n')document.body.classList.toggle('notes');if(e.key.toLowerCase()==='f')document.documentElement.requestFullscreen?.()});addEventListener('resize',resize);resize();draw();'''
output=ROOT/'docs/hoca_sunumu.html';output.write_text('<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Canine · Derin öğrenme sunumu</title><style>'+css+'</style>'+''.join(slides)+'<nav><span>← → slayt · N konuşma notları · F tam ekran</span><span><button id="prev">Önceki</button> <span id="count"></span> <button id="next">Sonraki</button> <button id="notes">Notlar</button></span></nav><script>'+script+'</script></html>')
